$serverPath=Join-Path $PSScriptRoot '..\server\src\admin-panel\index.js';$server=[IO.File]::ReadAllText($serverPath)
$postMarker="r.post('/api/admin/library-books',admin,async(req,res)=>"
$routes=@"
r.get('/api/admin/library-books/:slug',admin,async(req,res)=>{try{const item=await getBooks().findOne({slug:String(req.params.slug||'').trim()});if(!item)return res.status(404).json({message:'Book not found.'});const{_id,...book}=item;res.json({data:{id:_id.toString(),...book}})}catch(e){res.status(500).json({message:'Unable to load this book.'})}});
r.put('/api/admin/library-books/:slug',admin,async(req,res)=>{try{const txt=(v,n)=>String(v||'').trim().slice(0,n),title=txt(req.body.title,180),content=txt(req.body.content,2000000);if(title.length<2||content.length<20)return res.status(400).json({message:'Book title and at least 20 characters of text are required.'});const update={title,author:txt(req.body.author,160),category:txt(req.body.category,40)||'Books',language:txt(req.body.language,80)||'English',languageCode:txt(req.body.languageCode,12).toLowerCase()||'en',description:txt(req.body.description,800),license:txt(req.body.license,160)||'Public domain',sourceUrl:txt(req.body.sourceUrl,500),coverImageUrl:txt(req.body.coverImageUrl,1000),coverImageKey:txt(req.body.coverImageKey,1000),publicDomain:req.body.publicDomain!==false,published:!!req.body.published,content,pages:Array.isArray(req.body.pages)?req.body.pages.slice(0,5000):[],extraction:req.body.extraction&&typeof req.body.extraction==='object'?req.body.extraction:{},updatedAt:new Date()};const item=await getBooks().findOneAndUpdate({slug:String(req.params.slug||'').trim()},{`$set:update},{returnDocument:'after'});if(!item)return res.status(404).json({message:'Book not found.'});const{_id,...book}=item;res.json({data:{id:_id.toString(),...book},message:'Book updated successfully.'})}catch(e){console.error(e);res.status(500).json({message:'Unable to update this book.'})}});
"@
if(-not $server.Contains($postMarker)){throw 'Library book POST route not found'};$server=$server.Replace($postMarker,$routes+$postMarker)
[IO.File]::WriteAllText($serverPath,$server,[Text.UTF8Encoding]::new($false))

$adminPath=Join-Path $PSScriptRoot '..\admin-panel\app\page.tsx';$admin=[IO.File]::ReadAllText($adminPath)
$admin=$admin.Replace('import{FormEvent,useEffect,useState}from"react";','import{FormEvent,useEffect,useState}from"react";' + "`r`n" + 'import RichTextEditor from"./islamic-lifestyle/RichTextEditor";')
$admin=$admin.Replace('useState<any>({title:"",author:', 'useState<any>({slug:"",title:"",author:')
$admin=$admin.Replace('setBookForm({title:"",author:', 'setBookForm({slug:"",title:"",author:')
$oldFetch='r=await fetch(root+"/api/admin/library-books",{method:"POST",headers,body:JSON.stringify(bookForm)})'
$newFetch='r=await fetch(root+"/api/admin/library-books"+(bookForm.slug?"/"+encodeURIComponent(bookForm.slug):""),{method:bookForm.slug?"PUT":"POST",headers,body:JSON.stringify(bookForm)})'
if(-not $admin.Contains($oldFetch)){throw 'Book save fetch not found'};$admin=$admin.Replace($oldFetch,$newFetch)
$admin=$admin.Replace('setLibrary(items=>[j.data,...items]);setStats(current=>({...current,books:current.books+1,published:current.published+(j.data.published?1:0)}));','setLibrary(items=>bookForm.slug?items.map(item=>item.slug===bookForm.slug?j.data:item):[j.data,...items]);if(!bookForm.slug)setStats(current=>({...current,books:current.books+1,published:current.published+(j.data.published?1:0)}));')
$clearMarker='function clearBookForm(){'
$editFunction='async function editBook(book:any){setBookAction(book.slug);setBookMessage("Loading complete book...");try{const r=await fetch(api.replace(/\/$/,"")+"/api/admin/library-books/"+encodeURIComponent(book.slug),{headers}),j=await r.json();if(!r.ok)throw Error(j.message);setBookForm({...j.data,slug:book.slug,pages:j.data.pages||[],extraction:j.data.extraction||{}});setPreviewPage(0);setBookMessage("Editing "+j.data.title);window.scrollTo({top:0,behavior:"smooth"})}catch(e:any){setBookMessage(e.message||"Unable to load book") }finally{setBookAction("")}}'
if(-not $admin.Contains($clearMarker)){throw 'clearBookForm marker not found'};$admin=$admin.Replace($clearMarker,$editFunction+$clearMarker)
$oldContent='<label className="bookWide">Complete book text<textarea className="bookContent" value={bookForm.content} onChange={e=>setBookForm({...bookForm,content:e.target.value})} placeholder="Paste the complete verified book text here..." required minLength={20}/></label>'
$newContent='<div className="bookWide bookRichEditor"><label>Complete book text</label><RichTextEditor value={bookForm.content||""} onChange={html=>setBookForm({...bookForm,content:html})} api={api.replace(/\/$/,"")} token={token} onMessage={setBookMessage} recordId={`book:${bookForm.slug||"new"}:${bookForm.languageCode}`}/></div>'
if(-not $admin.Contains($oldContent)){throw 'Book content textarea not found'};$admin=$admin.Replace($oldContent,$newContent)
$oldActions='<span>{book.category||"Book"}</span><button type="button" className="clearBookButton" disabled={bookAction===book.slug} onClick={()=>void clearBook(book)}>{bookAction===book.slug?"Clearing...":"Clear"}</button>'
$newActions='<span>{book.category||"Book"}</span><button type="button" disabled={bookAction===book.slug} onClick={()=>void editBook(book)}>{bookAction===book.slug?"Loading...":"Edit"}</button><button type="button" className="clearBookButton" disabled={bookAction===book.slug} onClick={()=>void clearBook(book)}>Delete</button>'
if(-not $admin.Contains($oldActions)){throw 'Book row actions not found'};$admin=$admin.Replace($oldActions,$newActions)
$admin=$admin.Replace('<span>NEW LIBRARY CONTENT</span><h2>Add a Book</h2>','<span>{bookForm.slug?"EDIT LIBRARY CONTENT":"NEW LIBRARY CONTENT"}</span><h2>{bookForm.slug?"Edit Book":"Add a Book"}</h2>')
[IO.File]::WriteAllText($adminPath,$admin,[Text.UTF8Encoding]::new($false))
